#!/usr/bin/env node
import fs from 'node:fs'; import path from 'node:path'; import https from 'node:https'; import { execFileSync } from 'node:child_process';
const root=path.resolve(process.argv[2]||'dist');
if(!fs.existsSync(path.join(root,'index.html'))) throw new Error(`Smoke test failed: ${root}/index.html is missing`);
const html=fs.readFileSync(path.join(root,'index.html'),'utf8'); if(!html.trim() || !/<(?:div|main|body|script|html)\b/i.test(html)) throw new Error('Smoke test failed: index.html is empty or malformed');
const tmp=path.join(process.env.RUNNER_TEMP||'/tmp','wybuild-smoke-cert'); fs.mkdirSync(tmp,{recursive:true}); const key=path.join(tmp,'key.pem'), cert=path.join(tmp,'cert.pem');
execFileSync('openssl',['req','-x509','-newkey','rsa:2048','-nodes','-keyout',key,'-out',cert,'-days','1','-subj','/CN=localhost','-addext','subjectAltName=DNS:localhost,IP:127.0.0.1'],{stdio:'ignore'});
const server=https.createServer({key:fs.readFileSync(key),cert:fs.readFileSync(cert)},(req,res)=>{let p=decodeURIComponent(new URL(req.url,'https://localhost').pathname); if(p==='/'||p.endsWith('/'))p+='/index.html'; const f=path.join(root,p.replace(/^\//,'')); if(!f.startsWith(root)){res.writeHead(403);return res.end();} try{const data=fs.readFileSync(f);res.writeHead(200,{'Content-Type':f.endsWith('.js')?'text/javascript':f.endsWith('.css')?'text/css':f.endsWith('.html')?'text/html':'application/octet-stream'});res.end(data);}catch{res.writeHead(404);res.end('not found');}});
await new Promise(r=>server.listen(0,'127.0.0.1',r)); const port=server.address().port;
try { const { chromium }=await import('playwright'); const browser=await chromium.launch({headless:true,args:['--no-sandbox']}); const page=await browser.newPage({ignoreHTTPSErrors:true}); const errors=[]; const apiLeaks=[]; page.on('pageerror',e=>errors.push(String(e.message))); page.on('request',r=>{try{const u=new URL(r.url());if(u.hostname==='localhost'&&u.pathname.startsWith('/api/'))apiLeaks.push(`${r.method()} ${u.pathname}`);}catch{}}); await page.goto(`https://localhost:${port}/`,{waitUntil:'domcontentloaded',timeout:15000}); await page.waitForTimeout(1500); const body=await page.locator('body').innerText().catch(()=> ''); if(!body.trim())throw new Error('Smoke test failed: page body is empty.'); if(errors.length)throw new Error(`Smoke test JavaScript error: ${errors.join('; ')}`); if(apiLeaks.length)throw new Error(`Smoke test found same-origin API calls not rewritten: ${apiLeaks.join(', ')}`); await browser.close(); console.log('WyBuild native smoke test passed: non-empty shell, no uncaught JS errors, no localhost /api calls.'); } finally {server.close();}
